@startuml

class HospitalHouseMD {}

class Patient {
  + Id : string
}

class Doctor {
  + Id : string
}

class Diagnosis {
  + Id : string
}

class Treatment {
  + Id : string
  + stage : int
}

class TreatmentDatabase {
  + Id : string
}

class ConsentForm {
  + Id : string
  + isSigned : boolean
  + isRetracted : boolean
}

enum PriorityScore {
  HIGH
  LOW
}

class Illness {
  + Id : string
  + priorityScore : PriorityScore
}

HospitalHouseMD "1" *-- "*" Patient
HospitalHouseMD "1" *-- "*" Doctor
HospitalHouseMD "1" *-- "1" TreatmentDatabase

Patient "1" -- "*" Doctor
Patient "1" -- "*" Diagnosis
Doctor "1" -- "*" Diagnosis
Doctor "1" -- "*" Treatment

Diagnosis "1" -- "*" Treatment
TreatmentDatabase "1" -- "*" Treatment

Diagnosis "1" -- "1" Illness
Treatment "1" -- "1" Illness

Diagnosis "1" -- "0..1" ConsentForm
ConsentForm "1" -- "1" Patient

@enduml

